    for line in f:
        w5.append(json.loads(line))

# Load constraint file
with open('data/docred/ontology_constraints_docred.json') as f:
    constraints = json.load(f)

# Build domain-range map
dr_map = {}
for rel_id, info in constraints.get('relation_constraints', {}).items():
    dr_map[rel_id] = {
        'domain': set(info.get('domain', [])),
        'range': set(info.get('range', []))
    }

# Also try alias map
alias_map = {}
for rel_id, info in constraints.get('relation_constraints', {}).items():
    for alias in info.get('aliases', [info.get('name', '')]):
        alias_map[alias.lower()] = rel_id

# Check DR violations in w5
dr_violations = []
for doc in w5:
    parsed = doc.get('parsed_output')
    if parsed is None:
        continue
    for rel in parsed.get('relations', []):
        rel_type = rel.get('type', '')
        head_type = rel.get('head_type', '')
        tail_type = rel.get('tail_type', '')
        # Try to find the relation ID
        rel_id = alias_map.get(rel_type.lower(), rel_type)
        if rel_id in dr_map:
            domain = dr_map[rel_id]['domain']
            rng = dr_map[rel_id]['range']
            if domain and head_type not in domain:
                dr_violations.append({
                    'doc': doc['doc_id'], 'rel': rel_type, 'head': rel['head'],
                    'head_type': head_type, 'expected_domain': list(domain)[:3]
                })
