                dr_violations.append({
                    'doc': doc['doc_id'], 'rel': rel_type, 'tail': rel['tail'],
                    'tail_type': tail_type, 'expected_range': list(rng)[:3]
                })

print(f'DR violations found: {len(dr_violations)}')
for v in dr_violations[:10]:
    print(json.dumps(v))
